import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        byte[] b = System.in.readAllBytes();
        int v = 0;
        for (byte c : b) {
            if (c == 'U') v++;
            else if (c == 'D') v--;
        }
        System.out.println(v > 0 ? "U" : v < 0 ? "D" : "");
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

func main() {
	b, _ := io.ReadAll(os.Stdin)
	v := 0
	for _, c := range b {
		if c == 'U' {
			v++
		} else if c == 'D' {
			v--
		}
	}
	switch {
	case v > 0:
		fmt.Println("U")
	case v < 0:
		fmt.Println("D")
	default:
		fmt.Println("")
	}
}
